//! 🔎️ A real original instance executes and closes a phased guest call without rebuilding its Core or borrowing invented currency.
fn receive_scalar(runtime:&semio_plugin_interpreter_runtime::OwnedRuntime,state:&mut semio_plugin_interpreter_runtime::OwnedGuestInstance,cx:&mut semio_framework_job::StepContext<'_>)->Result<Option<semio_plugin_interpreter_runtime::OwnedOriginalCallResult>,semio_framework_job::OriginalTurnFailure>{let mut recipient=None;runtime.take_original_call_result_into_step(state,&mut recipient,cx)?;Ok(recipient)}

use semio_plugin_interpreter_runtime::{OwnedRuntime,OwnedSemioExport,OwnedOriginalCallStatus,OriginalCoreValue as Value};
use semio_framework_actor::{RetainedTurnInput,OriginalGuestExecutionBudget};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[global_allocator]
static TEST_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::RetainedCloneGrant;
fn clock()->Option<u64>{Some(1000)}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
fn observed<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn core_bytes(component:&[u8])->&[u8]{let mut pc=9;let mut length=0;let mut shift=0;loop{let byte=component[pc];pc+=1;length|=usize::from(byte&127)<<shift;shift+=7;if byte&128==0{break}}&component[pc..pc+length]}
/// 🧮️ Wasmtime verifies scalar output and physical receipts.
#[test]
fn original_owned_guest_call_preserves_source_core_machine_and_independent_execution(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let bytes=semio_plugin_interpreter_runtime::channel_fixture::owned_channel_guest(semio_os_kernel::CHANNEL_VERSION);let engine=wasmtime::Engine::default();let module=wasmtime::Module::new(&engine,core_bytes(&bytes)).unwrap();let mut store=wasmtime::Store::new(&engine,());let oracle=wasmtime::Instance::new(&mut store,&module,&[]).unwrap();let expected=oracle.get_typed_func::<(),i32>(&mut store,OwnedSemioExport::ChannelVersion.core_name()).unwrap().call(&mut store,()).unwrap();let runtime=OwnedRuntime::new(clock);let compiled=runtime.compile_component(&bytes).unwrap();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut startup=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_actor_startup(&compiled,cx)}).unwrap();let mut born=0;let mut released=0;
 for _ in 0..150{if startup.as_ref().unwrap().ready(){break}epoch+=1;let(_,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:1024,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;let owner=startup.as_mut().unwrap();let original_input=RetainedTurnInput::borrow_original(cx)?;let execution=owner.requires_execution().then(||OriginalGuestExecutionBudget{input:original_input,fuel:1,deadline_us:cx.deadline_us()});owner.advance_step(&compiled,cx,execution)?.result?;Ok(())}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}
 let mut state=None;for _ in 0..3{epoch+=1;state=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_actor_startup_step(&mut startup,&compiled,RetainedTurnInput::borrow_original(cx)?,cx)}).unwrap();if state.is_some(){break}}let mut state=state.unwrap();let arguments=[Value::I64(0);OwnedSemioExport::MAX_SCALAR_ARGUMENTS];let export=OwnedSemioExport::AcknowledgeActorFailureChunk;let index=match compiled.original_actor_module().export(export.core_name()){Some(ExportKind::Function(index))=>*index,_=>panic!("actual largest scalar export")};assert_eq!(compiled.original_actor_module().function_type(index).unwrap().parameters.len(),fixture["maximumArguments"].as_u64().unwrap()as usize);epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,export,&arguments,cx)}).unwrap());let mut maximum_vm=0;let mut maximum_ready=false;for _ in 0..512{epoch+=1;let(call,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;let input=RetainedTurnInput::borrow_original(cx)?;let execution=state.original_call_requires_execution().then(||OriginalGuestExecutionBudget{input,fuel:1,deadline_us:cx.deadline_us()});runtime.advance_original_call_step(&mut state,execution,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;if let Some(receipt)=call.execution{maximum_vm+=receipt.spent_fuel.unwrap()}if call.result.unwrap()==OwnedOriginalCallStatus::Ready{maximum_ready=true;break}}assert!(maximum_ready);assert_eq!(maximum_vm,fixture["expectedVm"].as_u64().unwrap());epoch+=1;let maximum=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;assert_eq!(runtime.original_call_export(&state,cx)?,Some(export));let result=receive_scalar(&runtime,&mut state,cx)?;assert_eq!(runtime.original_call_export(&state,cx)?,None);Ok(result)}).unwrap().unwrap();assert_eq!(maximum.value,Some(Value::I64(0)));assert!(!state.original_call_is_pending());let pointer=state.original_memory(0).unwrap().as_ptr();epoch+=1;let oversized=vec![Value::I64(0);fixture["maximumArguments"].as_u64().unwrap()as usize+1];let(result,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,OwnedSemioExport::ChannelVersion,&oversized,cx)}));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert!(!state.original_call_is_pending());assert_eq!(state.original_memory(0).unwrap().as_ptr(),pointer);epoch+=1;let(ready,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,OwnedSemioExport::ChannelVersion,&[],cx)}).unwrap());assert!(!ready);assert!(!state.original_call_is_pending());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,OwnedSemioExport::ChannelVersion,&[],cx)}).unwrap());let mut vm=0;for _ in 0..40{epoch+=1;let(call,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;let original_input=RetainedTurnInput::borrow_original(cx)?;let execution=state.original_call_requires_execution().then(||OriginalGuestExecutionBudget{input:original_input,fuel:1,deadline_us:cx.deadline_us()});runtime.advance_original_call_step(&mut state,execution,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;if let Some(execution)=call.execution{vm+=execution.spent_fuel.unwrap()}if call.result.unwrap()==OwnedOriginalCallStatus::Ready{break}}assert_eq!(vm,fixture["expectedVm"].as_u64().unwrap());assert_eq!(state.original_memory(0).unwrap().as_ptr(),pointer);epoch+=1;let(result,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;receive_scalar(&runtime,&mut state,cx)}).unwrap());assert!(result.is_none());assert!(state.original_call_is_pending());assert_eq!(heap,(0,0));let mut foreign=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let(result,heap)=observed(||foreign.turn(stock,|cx|{cx.bind_original_source_epoch(epoch+1)?;runtime.original_call_export(&state,cx)?;receive_scalar(&runtime,&mut state,cx)}));assert!(result.is_err());assert_eq!(heap,(0,0));foreign.retire(stock);epoch+=1;let result=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;assert_eq!(runtime.original_call_export(&state,cx)?,Some(OwnedSemioExport::ChannelVersion));receive_scalar(&runtime,&mut state,cx)}).unwrap().unwrap();assert_eq!(result.value,Some(Value::I32(expected)));assert_eq!((result.input.operation,result.input.generation),(71,3));assert!(!state.original_call_is_pending());epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_call_step(&mut state,OwnedSemioExport::ChannelVersion,&[],cx)}).unwrap());caller.cancel().cancel_now();for _ in 0..40{epoch+=1;let(done,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_call_step(&mut state,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;if done{break}}assert!(!state.original_call_is_pending());let mut state=Some(state);for _ in 0..100{if state.is_none(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_actor_step(&mut state,&compiled,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(state.is_none());assert_eq!(born,released);caller.retire(stock);
}

fn failure_budget(cx:&semio_framework_job::StepContext<'_>)->semio_framework_actor::OriginalJobBudget{semio_framework_actor::OriginalJobBudget{input:RetainedTurnInput::borrow_original(cx).unwrap(),retained_policy:cx.retained_grant(),fuel:cx.fuel_remaining(),deadline_us:cx.deadline_us(),cancelled:cx.is_cancelled()}}
fn scalar_ready(runtime:&OwnedRuntime,state:&mut semio_plugin_interpreter_runtime::OwnedGuestInstance,caller:&mut OriginalJobFixtureCaller,epoch:&mut u64){for _ in 0..4096{*epoch+=1;let ready=caller.turn(grant(),|cx|{cx.bind_original_source_epoch(*epoch)?;let execution=state.original_call_requires_execution().then(||OriginalGuestExecutionBudget{input:RetainedTurnInput::borrow_original(cx).unwrap(),fuel:1,deadline_us:cx.deadline_us()});Ok(runtime.advance_original_call_step(state,execution,cx)?.result?==OwnedOriginalCallStatus::Ready)}).unwrap();if ready{return}}panic!("actual failure scalar did not finish")}
fn input_round(runtime:&OwnedRuntime,state:&mut semio_plugin_interpreter_runtime::OwnedGuestInstance,caller:&mut OriginalJobFixtureCaller,epoch:&mut u64){for _ in 0..8192{*epoch+=1;let ready=caller.turn(grant(),|cx|{cx.bind_original_source_epoch(*epoch)?;let mut run=|cx:&mut semio_framework_job::StepContext<'_>|{let execution=state.original_unit_requires_execution().then(||OriginalGuestExecutionBudget{input:RetainedTurnInput::borrow_original(cx).unwrap(),fuel:1,deadline_us:cx.deadline_us()});Ok(runtime.advance_owned_original_unit_call_step(state,execution,cx)?.result?==OwnedOriginalCallStatus::Ready||state.original_unit_waiting_for_budget())};if cx.is_cancelled(){cx.with_original_retirement(run)}else{run(cx)}}).unwrap();if ready{return}}panic!("actual failed input did not finish")}
/// 🔐️ A real failed guest wire is fenced until its real acknowledged header is physically handed back.
#[test]
fn failed_input_cleanup_requires_actual_acknowledgment_and_same_header_deallocator(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/failed-input.json")).unwrap();let bytes=semio_plugin_interpreter_runtime::channel_fixture::owned_input_failure_guest(semio_os_kernel::CHANNEL_VERSION);let runtime=OwnedRuntime::new(clock);let compiled=runtime.compile_component(&bytes).unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(901),Generation(1),grant(),clock,1000000,1000000);let mut epoch=1;let mut startup=caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_actor_startup(&compiled,cx)}).unwrap();for _ in 0..4096{if startup.as_ref().unwrap().ready(){break}epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;let owner=startup.as_mut().unwrap();let execution=owner.requires_execution().then(||OriginalGuestExecutionBudget{input:RetainedTurnInput::borrow_original(cx).unwrap(),fuel:1,deadline_us:cx.deadline_us()});owner.advance_step(&compiled,cx,execution)?.result?;Ok(())}).unwrap();}let mut state=None;for _ in 0..8{epoch+=1;state=caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_actor_startup_step(&mut startup,&compiled,RetainedTurnInput::borrow_original(cx)?,cx)}).unwrap();if state.is_some(){break}}let mut state=state.unwrap();let mut donor=None;epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;cx.consume_retained(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:4,retained_capacity_bytes:4,..Default::default()})?;cx.consume_fuel(1);donor=Some(b"wire".to_vec());Ok(())}).unwrap();epoch+=1;let failed_epoch=epoch;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;assert!(runtime.begin_owned_original_unit_call_step(&mut state,&mut donor,failure_budget(cx),cx)?);Ok(())}).unwrap();input_round(&runtime,&mut state,&mut caller,&mut epoch);epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;let(header,_)=semio_plugin_guest_contract::original_actor_context::OriginalActorFixedReceipt::read(runtime.owned_original_unit_output(&state,cx)?.unwrap())?;assert_eq!(header.kind.input_disposition(),Some((false,false,true)));assert!(runtime.acknowledge_owned_original_unit_call_step(&mut state,cx)?);Ok(())}).unwrap();input_round(&runtime,&mut state,&mut caller,&mut epoch);assert!(state.original_unit_waiting_for_budget());
 for row in law["cases"].as_array().unwrap(){epoch+=1;let wanted=row["export"].as_str().unwrap();let export=*OwnedSemioExport::ALL.iter().find(|value|format!("{value:?}")==wanted).unwrap();caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;let mut args=vec![Value::I64((if row["epoch"].as_u64().unwrap()==law["failedEpoch"].as_u64().unwrap(){failed_epoch}else{failed_epoch-1})as i64),Value::I64(row["kind"].as_u64().unwrap()as i64)];if export==OwnedSemioExport::BorrowActorFailure{args.extend([Value::I64(cx.operation().0 as i64),Value::I64(cx.generation().0 as i64),Value::I64(0),Value::I64(1)]);}else{if export==OwnedSemioExport::AcknowledgeActorFailureChunk{args.extend([Value::I64(0),Value::I64(1)]);}args.extend(failure_budget(cx).scalar_arguments().map(|v|Value::I64(v as i64)));}assert_eq!(runtime.begin_original_call_step(&mut state,export,&args,cx).is_ok_and(|value|value),row["allowed"].as_bool().unwrap());Ok(())}).unwrap();for _ in 0..8{epoch+=1;if caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_call_step(&mut state,cx)}).unwrap(){break}}}
 epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;let mut args=vec![Value::I64(failed_epoch as i64),Value::I64(8)];args.extend(failure_budget(cx).scalar_arguments().map(|v|Value::I64(v as i64)));assert!(runtime.begin_original_call_step(&mut state,OwnedSemioExport::AcknowledgeActorFailure,&args,cx)?);Ok(())}).unwrap();scalar_ready(&runtime,&mut state,&mut caller,&mut epoch);let mut frame=None;let mut proof=None;epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;assert!(runtime.capture_actor_failure_ack_step(&state,&mut frame,cx)?);assert!(receive_scalar(&runtime,&mut state,cx)?.is_some());assert!(runtime.begin_original_call_step(&mut state,OwnedSemioExport::Deallocate,&[Value::I32(2048),Value::I32(144)],cx).is_err());assert!(runtime.begin_original_call_step(&mut state,OwnedSemioExport::Deallocate,&[Value::I32(3600),Value::I32(184)],cx)?);Ok(())}).unwrap();scalar_ready(&runtime,&mut state,&mut caller,&mut epoch);epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;assert!(runtime.finish_actor_failure_ack_step(&state,&mut frame,&mut proof,cx)?);assert!(receive_scalar(&runtime,&mut state,cx)?.is_some());assert!(runtime.authorize_failed_input_cleanup_step(&mut state,proof.as_ref().unwrap(),cx)?);Ok(())}).unwrap();caller.cancel().cancel_now();epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;cx.with_original_retirement(|cx|runtime.repeat_owned_original_unit_call_step(&mut state,failure_budget(cx),cx))}).unwrap();input_round(&runtime,&mut state,&mut caller,&mut epoch);epoch+=1;caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;cx.with_original_retirement(|cx|{assert!(runtime.acknowledge_owned_original_unit_call_step(&mut state,cx)?);Ok(())})}).unwrap();input_round(&runtime,&mut state,&mut caller,&mut epoch);for _ in 0..4096{epoch+=1;if caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_owned_original_unit_call_step(&mut state,cx)}).unwrap(){break}}assert!(!state.original_unit_is_pending());let mut state=Some(state);for _ in 0..4096{epoch+=1;if caller.turn(grant(),|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_actor_step(&mut state,&compiled,cx)}).unwrap(){break}}assert!(state.is_none());caller.retire(grant());
}
